    public static bool IsShotCalculation(string name) => name.EndsWith("power calculation", StringComparison.Ordinal) || name.EndsWith("crit calculation", StringComparison.Ordinal);
    public static bool IsGoalValueCalculation(string name) => name == "Goal value calculation" || name.EndsWith("goal value calculation", StringComparison.Ordinal);
    public static bool IsQuery(string name) => name == "Native blue-line crossing" || name == "Knockout duration calculation" || name == "Unused-player win reward" || name == "Opposing breakaway shot" || name == "Cultist incantation cycle" || name == "Defensive possession teleport" || name == "Opening team knockouts" || name == "Team knockout injury cycle" || name == "Puck knockout injury" || name == "Opening team shots" || name == "Recent team shot" || name == "Injury recovery" || name == "Celebrating scorer knockout" || name == "Bench talent reward" || name == "Completed-match attribute roll" || name == "Centre defender loans" || name == "Controlled possession display" || name == "Boss won" || name == "Act 1 boss won" || name == "Act 2 boss won" || name == "Random fart timer" || name == "Puck fart timer" || name == "Goal-post collision" || name == "Fart interaction" || name == "Talent expiry" || name == "Item acquired" || name == "Match cycle" || name == "Bench run retention" || name == "Opposing possession timer" || name == "Breakaway display" || name == "Without puck timer" || name == "Puck possession timer" || name == "Bodycheck movement" || name == "Talent reward choices" || name == "Player contract" || name == "Faceoff setup" || name == "Opponent goal reversal window" || name == "Golden Helmet ranking" || name == "Training attribute rewards" || name == "Coach choices" || name == "Shared puck value" || name == "Match winner calculation" || name == "Final whistle" || name == "Attribute bonus conversion" || name == "Training attribute conversion" || name == "Enraged duration calculation" || name == "Helmet equipment" || name == "Helmet effect calculation" || name == "Player reward eligibility" || name == "Permanent attribute change" || IsGoalValueCalculation(name) || IsShotCalculation(name) || name == "Goal verification" || name == "Match setup" || name == "Match rewards" || name == "Reward selection" || name == "Map event choices" || name == "Run started" || name == "Injury attempted" || name == "New injury" || name == "Contract expiry" || name == "Bench bonus";
    public static bool IsCondition(string name) => name.StartsWith("While ", StringComparison.Ordinal);
    public static string[] ResetChoices(string kind) => ForKind(kind).Where(t => !IsCondition(t) && !IsQuery(t) && !IsCompletion(t)).ToArray();
    public static bool IsCampaignEvent(string name) => name == "Training chosen";
    public static bool IsCompletion(string name) => IsCampaignEvent(name) || name == "Match won by mercy" || name == "Match won" || name == "Match completed" || name == "Shutout" || name == "Scoreless match" || name == "Scoreless match with an assist" || name == "Match with a broken stick";
    public static bool IsOpponentAction(string name) => new[] { "Opponent shot", "Opponent slapshot", "Opponent pass", "Opponent ability used", "Opponent knocked out", "Opponent crosses blue line", "Opponent goal" }.Contains(name);
    public static bool HasOtherPlayer(string name) => IsOpponentAction(name) || new[] { "Assist", "Goalie assist", "Check", "Checked", "Knockout", "Teammate knockout", "Knocked out", "Pokecheck", "Pokechecked", "Interception", "Pass intercepted", "Injury caused", "Goalie receives shot", "Pass sent", "Pass received" }.Contains(name);
    public static bool HasPuckFlow(string name) => HasShotFlow(name) || new[] { "Opponent pass", "Pass sent", "Goalie blocker rebound", "Goalie glove rebound", "Shot rebounds off goalie" }.Contains(name);
    public static bool HasShotFlow(string name) => new[] { "Opponent shot", "Opponent slapshot", "Bat", "Shot", "Slapshot", "Wrist shot", "One-timer", "Critical shot", "Non-critical shot" }.Contains(name);
    public static bool IsGoalieEvent(string name) => name.StartsWith("Goalie ", StringComparison.Ordinal) || name == "Shutout" || name == "Goal conceded";
    public static bool HasForwardActor(string kind, string trigger) => kind != CustomRewardDefinition.CustomGoalieTalents && !IsGoalieEvent(trigger);
    public static string ConditionText(string name) => name == "While owned" ? "while owned" : name.ToLowerInvariant().Replace("while score tied", "while the score is tied");
    public static int EndDirection(bool north, float velocityZ, float intendedZ) {
        float direction = north ? 1 : -1;
        return velocityZ * direction > 0 || intendedZ * direction > 0 ? 1 : velocityZ * direction < 0 || intendedZ * direction < 0 ? -1 : 0;
    }
    public static string[] ForKind(string kind) => All.Where(t => kind == CustomRewardDefinition.CustomRelics || t.Name != "Team knocks out referee" && t.Name != "Opposing goalie save").Where(t => kind == CustomRewardDefinition.CustomTalents || t.Name != "While in blue-line shot range").Where(t => kind == CustomRewardDefinition.CustomRelics || t.Name != "While classified as a benchwarmer" && t.Name != "While wearing Golden Helmet against a boss").Where(t => (t.Name != "Random fart timer" || kind == CustomRewardDefinition.CustomTalents) && (t.Name != "Puck fart timer" || kind == CustomRewardDefinition.CustomRelics)).Where(t => kind == CustomRewardDefinition.CustomChaosTalents || t.Name != "While moving toward own end" && t.Name != "While moving toward opposing end").Where(t => kind == CustomRewardDefinition.CustomTalents || kind == CustomRewardDefinition.CustomChaosTalents || t.Name != "While outside period 1").Where(t => kind == CustomRewardDefinition.CustomRelics || t.Name != "While wearing a special helmet" && t.Name != "While in final 20 seconds" && t.Name != "While team has no opposing knockouts" && t.Name != "While size L, XL or XXL").Where(t => !IsCampaignEvent(t.Name) || kind == CustomRewardDefinition.CustomRelics).Where(t => !IsOpponentAction(t.Name) || t.Name == "Opponent goal" || kind == CustomRewardDefinition.CustomRelics).Where(t => t.Name != "Match setup" && t.Name != "Referee knocked out" || kind == CustomRewardDefinition.CustomRelics).Where(t => kind == CustomRewardDefinition.CustomGoalieTalents
        ? GoalieTrigger(t.Name)
        : kind == CustomRewardDefinition.CustomRelics || !(t.Name.StartsWith("Goalie ") || t.Name == "Shutout" || t.Name == "Goal conceded")).Select(t => t.Name).ToArray();
    private static bool GoalieTrigger(string trigger) => new[] { "Goalie faces shot on net", "Goalie observes shot on either net", "Opponent breakaway", "Period started", "Last 30 seconds of period", "Last 45 seconds of period" }.Contains(trigger)
        || CommonGoalieTrigger(trigger);
    private static bool CommonGoalieTrigger(string trigger) =>
        new[] { "While owned", "While holding puck", "While without puck", "While enraged", "While score tied", "While leading", "While trailing", "While opponent has puck", "While team has puck", "While in period 1", "While in period 2", "While in period 3", "Goalie receives shot", "Goalie picks up puck", "Goalie desperate save", "Goalie pokecheck", "Goalie blocker rebound", "Goalie glove rebound", "Goalie assist", "Goal conceded", "Shutout", "Pass sent", "Ability used", "Enraged", "Match started", "Match completed", "Match won", "Match rewards", "Reward selection", "Map event choices" }.Contains(trigger);
    public static string Help(string name) => All.FirstOrDefault(t => t.Name == name)?.Example ?? "";
    public static string Action(string name, int count) {
        var entry = All.FirstOrDefault(t => t.Name == name) ?? throw new ArgumentException("Unknown trigger: " + name);
        return entry.Action + (count == 1 ? "" : " " + count + " times");
    }
}
